/** Offline commands that read the agent project on disk. */
import { cmdManifest } from "../../cli-manifest.js";
import { formatDiagnostics, formatValidateJson, projectInfo, resolveAgentMounts, } from "../../discovery.js";
import { defineCommand } from "../command.js";
import { dirFlag, fieldsFlag, jsonFlag } from "../flags.js";
import { parseFields, printJson, projectFields } from "../output.js";
function hasErrors(project) {
    return project.diagnostics.some((diagnostic) => diagnostic.severity === "error");
}
export const validateCommand = defineCommand({
    name: "validate",
    group: "develop",
    summary: "Check the project and exit 1 on any error diagnostic.",
    flags: { ...dirFlag, ...jsonFlag },
    effect: "read",
    examples: ["agent-sdk validate", "agent-sdk validate --dir ./agents --json"],
    async run({ values }) {
        const mounts = await resolveAgentMounts(values.dir);
        if (values.json === true) {
            process.stdout.write(formatValidateJson(mounts));
        }
        else {
            for (const { slug, project } of mounts) {
                const label = slug === "" ? project.name : `${slug} (${project.name})`;
                if (project.diagnostics.length === 0) {
                    process.stdout.write(`ok: ${label} has no diagnostics\n`);
                    continue;
                }
                process.stdout.write(`${label}:\n${formatDiagnostics(project.diagnostics)}\n`);
            }
        }
        return mounts.some((mount) => hasErrors(mount.project)) ? 1 : 0;
    },
});
export const infoCommand = defineCommand({
    name: "info",
    aliases: [
        {
            name: "manifest",
            now: "info --view manifest",
            argv: (rest) => [...rest, "--view", "manifest"],
        },
    ],
    group: "develop",
    summary: "Print the discovered agent surface: tools, skills, channels, and more.",
    description: `
One agent prints its info object. A folder of agents prints { agents: [...] };
--fields then applies to each agent. --view manifest prints the offline deploy
manifest instead: events, egress, routes, and the /v1/info payload. No
network.`,
    flags: {
        ...dirFlag,
        view: {
            type: "string",
            value: "<view>",
            choices: ["info", "manifest"],
            default: "info",
            description: "info: the agent surface. manifest: the offline deploy manifest.",
        },
        ...jsonFlag,
        ...fieldsFlag,
    },
    effect: "read",
    examples: [
        "agent-sdk info --json",
        "agent-sdk info --json --fields name,tools.name",
        "agent-sdk info --view manifest --json",
    ],
    async run({ values }) {
        if (values.view === "manifest") {
            return cmdManifest({ dir: values.dir, json: values.json === true });
        }
        const mounts = await resolveAgentMounts(values.dir);
        if (values.json === true) {
            const fields = parseFields(values.fields);
            const payload = mounts.length === 1 && mounts[0]?.slug === ""
                ? projectFields(projectInfo(mounts[0].project), fields)
                : {
                    agents: mounts.map(({ slug, project }) => projectFields({ slug, ...projectInfo(project) }, fields)),
                };
            printJson(payload);
            return 0;
        }
        const single = mounts.length === 1 && mounts[0]?.slug === "" ? mounts[0] : undefined;
        if (single === undefined) {
            printAgentList(values.dir, mounts);
            return mounts.some((mount) => hasErrors(mount.project)) ? 1 : 0;
        }
        printProjectInfo(single.project);
        return hasErrors(single.project) ? 1 : 0;
    },
});
function printAgentList(dir, mounts) {
    process.stdout.write(`${mounts.length} agents under ${dir}:\n\n`);
    for (const { slug, project } of mounts) {
        const info = projectInfo(project);
        process.stdout.write(`  /${slug}  —  ${info.name}  (${formatModel(info.model)}, ${info.tools.length} tools, ${info.channels.length} channels)\n`);
    }
}
function printProjectInfo(project) {
    const info = projectInfo(project);
    const lines = [
        `agent: ${info.name}`,
        `model: ${formatModel(info.model)}`,
        `mcp: ${info.mcp.path} (${info.mcp.tools.join(", ")})`,
    ];
    if (info.instructions !== undefined) {
        lines.push(`instructions: ${info.instructions.chars} chars`);
    }
    lines.push(section("tools", info.tools.map((t) => `${t.name} — ${t.description}`)), section("skills", info.skills.map((s) => `${s.name} — ${s.description}`)), section("extensions", info.extensions.map((e) => {
        const contributed = [...e.tools, ...e.skills].join(", ") || "(nothing contributed)";
        const egress = e.hosting?.egressDomains ?? [];
        return egress.length === 0
            ? `${e.name} — ${contributed}`
            : `${e.name} — ${contributed}; egress: ${egress.join(", ")}`;
    })), section("MCP connections", info.connections.map((c) => `${c.name} — ${c.transport}`)), section("subagents", info.subagents.map((s) => `${s.name} — ${s.description ?? ""}`)), section("channels", info.channels.map((c) => `${c.id}: ${c.routes.map((r) => `${r.method} ${r.url}`).join(", ") || "(events only)"}`)), section("schedules", info.schedules.map((s) => `${s.name} (${s.cron}, ${s.kind})`)), section("hooks", info.hooks), section("hosting egress domains", info.hosting?.egressDomains ?? []), section("hosting secret names", info.hosting?.secretNames ?? []));
    if (info.diagnostics.length > 0) {
        lines.push(`\ndiagnostics:\n${formatDiagnostics(info.diagnostics)}`);
    }
    process.stdout.write(`${lines.filter((line) => line !== "").join("\n")}\n`);
}
function section(title, items) {
    if (items.length === 0) {
        return "";
    }
    return `${title}:\n${items.map((item) => `  - ${item}`).join("\n")}`;
}
function formatModel(model) {
    if (model === undefined) {
        return "(unset)";
    }
    if (typeof model === "string") {
        return model;
    }
    return JSON.stringify(model);
}
